def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opps:
        if hp <= 3 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    urgent_opps = 0
    rich_opps = 0
    for opp in alive_opps:
        if opp.get('budget', 0) >= budget:
            rich_opps += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            urgent_opps += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    survival_urgency = 0.0
    if hp <= 2:
        survival_urgency += 0.6
    elif hp <= 4:
        survival_urgency += 0.35
    if no_water_days >= 2:
        survival_urgency += 0.5
    elif no_water_days == 1:
        survival_urgency += 0.2
    if day >= 8:
        survival_urgency += 0.1

    pressure = avg_prev * 0.55 + highest_prev * 0.35 + urgent_opps * 4.0 + rich_opps * 2.0

    base = DAILY_SALARY * (0.22 + 0.38 * scarcity) + pressure * 0.28

    if highest_prev >= 130:
        if survival_urgency < 0.45:
            bid = DAILY_SALARY * (0.18 + 0.18 * scarcity)
        else:
            bid = max(base, highest_prev * 0.72)
    elif highest_prev >= 85:
        if survival_urgency < 0.3 and scarcity < 0.45:
            bid = DAILY_SALARY * 0.24
        else:
            bid = max(base, avg_prev + 3.0)
    else:
        bid = max(base, avg_prev + 2.0 if avg_prev > 0 else DAILY_SALARY * 0.34)

    if survival_urgency >= 0.8:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif survival_urgency >= 0.5:
        bid = max(bid, DAILY_SALARY * 0.78)
    elif survival_urgency >= 0.25:
        bid = max(bid, DAILY_SALARY * 0.58)

    if supply >= 23 and survival_urgency < 0.4:
        bid *= 0.82
    elif supply <= 17:
        bid *= 1.12

    if day == 1 and survival_urgency < 0.4:
        bid = min(bid, DAILY_SALARY * 0.5)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * 1.2
    if budget < reserve_floor and survival_urgency < 0.5:
        bid = min(bid, max(0.0, budget - reserve_floor * 0.35))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Pressure model from yesterday: if someone paid very high, they likely tried to outbid for scarce water.
    # We counter with a slightly lower but still competitive bid.
    scarcity_factor = 0.0
    if supply <= MIN_SUPPLY + 1e-9:
        scarcity_factor = 1.0
    elif supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        scarcity_factor = 0.6
    else:
        scarcity_factor = 0.3

    # Base bid: ensure we can keep hp stable; if we are already in danger, bid more.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base = DAILY_SALARY * (0.75 + 0.15 * scarcity_factor)
    elif my_hp <= 4.0 or my_no_water_days == 1:
        base = DAILY_SALARY * (0.55 + 0.15 * scarcity_factor)
    else:
        base = DAILY_SALARY * (0.45 + 0.10 * scarcity_factor)

    # If yesterday saw extreme bids, adjust to avoid being outbid.
    extreme_threshold = DAILY_SALARY * 0.95
    if highest_prev_bid >= extreme_threshold:
        # Bid just below the extreme to win with high probability without fully matching.
        target = min(my_budget, highest_prev_bid * 0.92)
        # Ensure target is not too low relative to our base.
        target = max(target, base)
        return max(0.0, min(my_budget, target))

    # Otherwise, try to beat typical bids without starting a full war.
    # Use a conservative increment over the highest previous bid if it is not too high.
    war_threshold = DAILY_SALARY * 0.70
    if highest_prev_bid >= war_threshold:
        target = min(my_budget, highest_prev_bid * 0.85)
        target = max(target, base)
        return max(0.0, min(my_budget, target))

    # Default: bid near base, but scaled by how much supply exists.
    # If supply is higher, we can bid less.
    supply_scale = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_scale = max(0.0, min(1.0, supply_scale))
    bid = base * (1.0 - 0.25 * supply_scale)

    # Never bid above budget or below a minimal floor.
    min_bid_floor = 1.0
    bid = max(min_bid_floor, min(my_budget, bid))
    return float(bid)

